// Clinical Entities (NER)
export type EntityType = 
  | 'symptom' 
  | 'diagnosis' 
  | 'medication' 
  | 'vital_sign' 
  | 'allergy' 
  | 'medical_history'

export interface ClinicalEntity {
  id: string
  type: EntityType
  text: string
  normalizedText?: string // SNOMED CT or ICD-10 mapping
  code?: string // Medical code (SNOMED/ICD-10)
  confidence: number
  timestamp: Date
}

