// Transcription
export interface TranscriptionSegment {
  id: string
  speaker: 'doctor' | 'patient'
  text: string
  timestamp: Date
  entities: ClinicalEntity[]
}

// Patient Information
export interface PatientInfo {
  id: string
  name?: string
  age?: number
  gender?: 'M' | 'F' | 'O'
  documentId?: string
}

// Triage Session
export interface TriageSession {
  id: string
  patient: PatientInfo
  startTime: Date
  endTime?: Date
  transcription: TranscriptionSegment[]
  entities: ClinicalEntity[]
  triagePriority?: TriagePriority
  chiefComplaint?: string
  reasoning?: string
  status: 'recording' | 'processing' | 'completed' | 'exported'
}

// FHIR Resource (Simplified)
export interface FHIREncounter {
  resourceType: 'Encounter'
  id: string
  status: string
  class: {
    system: string
    code: string
    display: string
  }
  priority?: {
    coding: Array<{
      system: string
      code: string
      display: string
    }>
  }
  subject: {
    reference: string
    display?: string
  }
  period: {
    start: string
    end?: string
  }
  reasonCode?: Array<{
    coding: Array<{
      system: string
      code: string
      display: string
    }>
    text: string
  }>
}
